import{_ as a,o as t,c as n,N as i}from"./chunks/framework.11ad0a06.js";const u=JSON.parse('{"title":"Execution Modes","description":"","frontmatter":{"sidebarDepth":2,"collapsable":false},"headers":[],"relativePath":"en/guide/mode.md","lastUpdated":1795525255000}'),o={name:"en/guide/mode.md"};function s(r,e,d,p,c,l){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="execution-modes" tabindex="-1">Execution Modes <a class="header-anchor" href="#execution-modes" aria-label="Permalink to &quot;Execution Modes&quot;">​</a></h1><p><img src="https://vfiles.gtimg.cn/wuji_dashboard/xy/test_wuji_damy/F0NYfpHl.jpeg" alt="Wujie execution modes flowchart"></p><p>In a micro-frontend architecture, sub-apps are repeatedly activated and deactivated as users navigate across pages in the main app. In Wujie, whether a sub-app enables Keep-Alive mode and whether it implements lifecycle adaptation determines which of three execution flows it follows.</p><h2 id="keep-alive-mode" tabindex="-1">Keep-Alive Mode <a class="header-anchor" href="#keep-alive-mode" aria-label="Permalink to &quot;Keep-Alive Mode&quot;">​</a></h2><p>Setting <a href="/doc/en/api/startApp.html#alive">alive</a> to <code>true</code> enables <strong>Keep-Alive Mode</strong>, preserving internal state and routing across page switches.</p><p>In Keep-Alive Mode, the sub-app renders only once. When navigating away, the Web Component holding the sub-app&#39;s DOM stays cached in memory. When the sub-app is activated again, Wujie re-attaches that cached Web Component directly into the container.</p><p>Changing <a href="/doc/en/api/startApp.html#url">url</a> in Keep-Alive Mode will <strong>not</strong> navigate the sub-app to a new route; instead, use <a href="/doc/en/guide/communication.html">Communication</a> (such as <code>EventBus</code>) to trigger route changes inside the sub-app.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>A keep-alive sub-app instance is never destroyed, so it continues to receive <code>bus</code> events even when switched out of view. In contrast, non-keep-alive sub-apps have all of their event listeners cleared when switched away and must re-subscribe on their next mount.</p></div><h2 id="singleton-mode" tabindex="-1">Singleton Mode <a class="header-anchor" href="#singleton-mode" aria-label="Permalink to &quot;Singleton Mode&quot;">​</a></h2><p>When <code>alive</code> is <code>false</code> and the sub-app has completed <a href="/doc/en/guide/start.html#lifecycle-adaptation">Lifecycle Adaptation</a>, it runs in <strong>Singleton Mode</strong>.</p><p>When navigating away from the sub-app, Wujie invokes <code>window.__WUJIE_UNMOUNT</code> to destroy the current app instance. When navigating back, Wujie invokes <code>window.__WUJIE_MOUNT</code> to render a fresh instance while reusing the same sandbox.</p><p>In Singleton Mode, updating <a href="/doc/en/api/startApp.html#url">url</a> navigates the sub-app to the corresponding route.</p><p>If multiple menu items in the main app point to different pages of the same sub-app, give them the <strong>same <code>name</code></strong>. They will share a single <code>wujie</code> instance and JavaScript <code>iframe</code>, and switching between those pages becomes: destroy current app instance → sync new route → create new app instance.</p><h2 id="rebuild-mode" tabindex="-1">Rebuild Mode <a class="header-anchor" href="#rebuild-mode" aria-label="Permalink to &quot;Rebuild Mode&quot;">​</a></h2><p>When a sub-app neither enables Keep-Alive Mode nor implements lifecycle adaptation, it runs in <strong>Rebuild Mode</strong>. On every switch, Wujie destroys both the Web Component holding the DOM and the <code>iframe</code> running the JavaScript, tearing down the entire <code>wujie</code> instance and sub-app instance.</p><p>In Rebuild Mode, changing <a href="/doc/en/api/startApp.html#url">url</a> navigates the sub-app to the target route. However, if <a href="/doc/en/guide/sync.html">Route Sync</a> is enabled and the sub-app&#39;s synced route query parameter is already present in the main app&#39;s URL, changing <code>url</code> will not override it — because rebuilding re-initializes the sub-app and synced query parameters take highest precedence.</p><p>To programmatically trigger a full rebuild, use <a href="/doc/en/api/refreshApp.html">refreshApp</a>.</p>',17)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
